-- 025_delete_zombie_sidebar_items.sql
-- Deletes sidebar_menu_items that are (a) not linked to any role via
-- role_sidebar_menus AND (b) whose URL resolves to no existing page or
-- dashboard component. These are dead registry entries invisible to every
-- user (mostly duplicates of concepts already covered by other menu items).
--
-- Applied to live DB: 2026-08-10

DELETE FROM `role_sidebar_menus`
WHERE `menu_item_id` IN (
    204,205,271,273,311,312,320,323,336,346,348,349,353,367,368,370,371,373,374,
    392,393,394,395,396,404,405,410,413,414,416,417,419,420,451,453,458,459,461,
    465,467,468,505,511,523,526,529,535,551,560,561,563,903,915,921,924,925,934,
    935,944,954,1055,1056,1062,1071,1077,1078,1087,1105,1107,1112,1113,1116,1120,
    1124,1126,1130,1131,1132,1134,1136,1144,1146,1150,1151,1152,1185,1188,1229,
    1233,1278,1319,99999
);

DELETE FROM `sidebar_menu_items`
WHERE `id` IN (
    204,205,271,273,311,312,320,323,336,346,348,349,353,367,368,370,371,373,374,
    392,393,394,395,396,404,405,410,413,414,416,417,419,420,451,453,458,459,461,
    465,467,468,505,511,523,526,529,535,551,560,561,563,903,915,921,924,925,934,
    935,944,954,1055,1056,1062,1071,1077,1078,1087,1105,1107,1112,1113,1116,1120,
    1124,1126,1130,1131,1132,1134,1136,1144,1146,1150,1151,1152,1185,1188,1229,
    1233,1278,1319,99999
);
